import React from 'react';
import { Camera, BookOpen, Coffee, Award, Wifi, MonitorPlay } from 'lucide-react';

const facilities = [
    { title: "Central Library", icon: BookOpen, span: "col-span-2 md:col-span-2 row-span-2", bg: "bg-coral", text: "text-white", desc: "Over 50,000 volumes with digital access." },
    { title: "Advanced Labs", icon: MonitorPlay, span: "col-span-2 md:col-span-1 row-span-1", bg: "bg-gold", text: "text-coral2", desc: "State-of-the-art research centers." },
    { title: "Smart Campus", icon: Wifi, span: "col-span-2 md:col-span-1 row-span-1", bg: "bg-slate-100", text: "text-coral", desc: "1GBPS Wi-Fi coverage across campus." },
    { title: "Sports Complex", icon: Award, span: "col-span-2 md:col-span-1 row-span-1", bg: "bg-coral2", text: "text-white", desc: "Indoor stadiums and massive outdoor grounds." },
    { title: "Cafeteria", icon: Coffee, span: "col-span-2 md:col-span-2 row-span-1", bg: "bg-white border border-slate-200", text: "text-coral", desc: "Hygienic, vibrant dining area for students." },
];

const Gallery = () => {
    return (
        <section id="campus-life" className="py-24 bg-slate-50 relative overflow-hidden">
            {/* Background elements */}
            <div className="absolute top-0 right-0 w-64 h-64 bg-gold opacity-10 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2"></div>

            <div className="max-w-7xl mx-auto px-6 relative z-10">
                <div className="text-center mb-16">
                    <span className="text-gold font-bold tracking-[0.2em] uppercase text-sm mb-3 block">Campus Life</span>
                    <h2 className="text-4xl md:text-5xl font-display font-extrabold text-coral">World-Class Facilities</h2>
                    <div className="w-20 h-1.5 bg-gradient-to-r from-coral via-gold to-coral mx-auto mt-6 rounded-full"></div>
                </div>

                <div className="grid grid-cols-2 md:grid-cols-4 grid-rows-auto md:grid-rows-2 gap-4 lg:gap-6 min-h-[500px]">
                    {facilities.map((fac, idx) => (
                        <div key={idx} className={`${fac.span} ${fac.bg} ${fac.text} rounded-3xl p-8 flex flex-col justify-end relative overflow-hidden group hover:scale-[1.02] transition-transform duration-500 shadow-sm cursor-pointer`}>
                            {/* Abstract decorative shape */}
                            <div className="absolute -right-8 -top-8 opacity-10 group-hover:scale-110 transition-transform duration-700 ease-out">
                                <fac.icon size={160} />
                            </div>

                            <div className="relative z-10">
                                <div className="mb-4 opacity-90 transform group-hover:-translate-y-2 transition-transform duration-300">
                                    <fac.icon size={36} />
                                </div>
                                <h3 className="text-2xl lg:text-3xl font-display font-bold mb-2">{fac.title}</h3>
                                <p className={`text-sm opacity-80 font-body transform translate-y-4 opacity-0 group-hover:translate-y-0 group-hover:opacity-100 transition-all duration-500 ease-out ${fac.bg === 'bg-white border border-slate-200' || fac.bg === 'bg-slate-100' ? 'text-slate-600' : 'text-white/90'}`}>{fac.desc}</p>
                            </div>
                        </div>
                    ))}

                    {/* View Gallery Button Tile */}
                    <div className="col-span-2 md:col-span-1 row-span-1 bg-transparent border-2 border-dashed border-coral/30 rounded-3xl p-8 flex flex-col items-center justify-center hover:border-coral hover:bg-coral/5 transition-all duration-300 cursor-pointer group">
                        <Camera size={40} className="text-gold mb-3 group-hover:text-coral group-hover:scale-110 transition-all duration-300" />
                        <span className="font-bold text-coral group-hover:text-coral2 uppercase tracking-widest text-sm text-center">Full Gallery</span>
                    </div>
                </div>
            </div>
        </section>
    );
};

export default Gallery;
